def generate_balance_sheet(assets, liabilities, equity):

    data = {
        'Assets': list(assets.keys()),
        'Amount': list(assets.values())
    }
    assets_df = pd.DataFrame(data)

    data = {
        'Liabilities': list(liabilities.keys()),
