                return ['I', 'I', 'I', 'I']
            else:
                return ['I', 'I', 'I', 'I']
        elif piece == 'O':
            return ['O', 'O', 'O', 'O']
        elif piece == 'T':
            if direction == 'clockwise':
                return ['T', 'T', 'T', '_']
            else:
                return ['_', 'T', 'T', 'T']
        elif piece == 'S':
            if direction == 'clockwise':
                return ['_', 'S', 'S', 'S']
            else:
                return ['S', 'S', '_', 'S']
        elif piece == 'Z':
            if direction == 'clockwise':
                return ['Z', 'Z', '_', 'Z']
            else:
                return ['_', 'Z', 'Z', 'Z']
        elif piece == 'J':
            if direction == 'clockwise':
                return ['J', '_', '_', 'J']
            else:
                return ['_', 'J', 'J', 'J']
        elif piece == 'L':
            if direction == 'clockwise':
                return ['_', '_', 'L', 'L']
            else:
                return ['L', 'L', 'L', '_']

