        elif piece == 'O':
            self.players[player_index].extend([(x, y), (x, y + 1), (x + 1, y), (x + 1, y + 1)])
        elif piece == 'T':
            self.players[player_index].extend([(x, y), (x - 1, y), (x + 1, y), (x, y + 1)])
